const statusMeta = { ready: { label: 'Можно писать', cls: 'ready' }, contacted: { label: 'Написал', cls: 'muted' }, review: { label: 'Проверить', cls: 'review' }, progress: { label: 'Ответил', cls: 'progress' }, won: { label: 'Встреча / сделка', cls: 'won' }, lost: { label: 'Пауза', cls: 'muted' }, muted: { label: 'Новый', cls: 'muted' } };

let leads = loadLeads();
let currentFocus = null;
