function loadLeads() { try { const stored = localStorage.getItem('ukalead-leads'); return stored ? JSON.parse(stored) : seedLeads; } catch { return seedLeads; } }
function persist() { localStorage.setItem('ukalead-leads', JSON.stringify(leads)); }
function esc(value) { return String(value ?? '').replace(/[&<>"']/g, c => ({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#039;'}[c])); }
function initials(name) { return name.split(/\s+/).slice(0,2).map(p => p[0]).join('').toUpperCase(); }
function serviceClass(service) { return serviceMeta[service]?.color || 'cyan'; }
function scoreClass(score) { return score >= 80 ? 'high' : score >= 65 ? 'med' : 'low'; }
function sourceLabel(l) { const source=String(l.source||'').toLowerCase(); const evidence=String(l.evidence||'').toLowerCase(); return l.sourceType === 'yandex' || source.includes('yandex.') || evidence.includes('яндекс') ? 'Яндекс Карт' : l.sourceType === 'google' || source.includes('google.') || evidence.includes('google maps') ? 'Google Maps' : '2ГИС'; }
function leadContext(l) { const category = l.category && l.category !== 'Организация' ? `в нише «${String(l.category).toLowerCase()}»` : ''; const fact = String(l.evidence || '').split(' · ').filter(Boolean).find(x => !x.startsWith('Распарсено') && !x.startsWith('Найдено в')); const review=l.reviewAnalytics; const reviewHook=review?.sufficient ? `По отзывам видно: ${review.offerAngle}.` : ''; const siteHook=l.websiteAudit?.issues?.length ? `По сайту вижу: ${l.websiteAudit.issues[0]}` : ''; return { category, fact: fact || 'уже работаете с клиентами в городе', contact: l.phone || l.whatsapp || '', reviewHook, siteHook }; }
function auditOfferData(l) { const review=l.reviewAnalytics||null; const site=l.websiteAudit||null; const source=sourceLabel(l); const topics=(review?.topTopics||[]).slice(0,2).map(topic=>topic.name); const strengths=[]; if(review?.sufficient&&topics.length) strengths.push(`клиенты чаще всего отмечают ${topics.join(' и ')}`); else if(review?.sufficient) strengths.push('есть подтверждённый спрос и материал для доверительной коммуникации'); const siteStrengths=(site?.strengths||[]).slice(0,2).map(item=>String(item).replace(/^есть\s+/i,'')); if(siteStrengths.length) strengths.push(`на сайте уже доступны ${siteStrengths.join(' и ')}`); if(!strengths.length) strengths.push(l.rating?`в ${source} уже есть рейтинг ${l.rating}`:`компания представлена в публичном поле ${source}`); const gaps=[]; if(site?.issues?.length) gaps.push(String(site.issues[0]).replace(/[.!?]+$/,'')); if(review?.sufficient&&review.negative>0) gaps.push(`в отзывах есть ${review.negative} сигнал${review.negative===1?'':'а'} для отдельной отработки`); if(!review?.sufficient) gaps.push('публичных отзывов пока недостаточно для уверенного вывода'); if(!gaps.length) gaps.push('критичных пробелов в первом проходе не видно — стоит проверить отдельный оффер и путь заявки'); const recommendation=l.service==='service'?'настроить абонентское IT-сопровождение: резервные копии, доступы, безопасность и быстрые заявки сотрудников':l.service==='dev'?'сделать короткую форму расчёта и отдельную страницу заявки':l.service==='ai'?(review?.sufficient?'превратить сильные отзывы в кейсы, Reels и серию контента на 14 дней':'запустить 14-дневный AI-контент-пакет'):site?.issues?.length?'обновить путь заявки на сайте и подключить локальную рекламную связку':'собрать мини-воронку с понятным оффером и измерением обращений'; const message=`Здравствуйте! ${l.name}, провёл быстрый анализ вашей компании по открытым данным ${source}${site?.url?' и сайта':''}. Сильная сторона: ${strengths[0]}. Точка роста: ${gaps[0]}. Предлагаю такой первый шаг: ${recommendation}. Могу за 15 минут показать первый вариант и что именно измерять по заявкам. Если актуально, пришлю план из 3 шагов.`; return { strengths, gaps, recommendation, message }; }
function auditOfferBlock(l) { if(!l.reviewAnalytics&&!l.websiteAudit)return ''; const data=auditOfferData(l); return `<div class="audit-offer-panel"><div class="offer-panel-head"><div><div class="detail-label">Оффер по аудиту</div><span class="offer-hint">Сообщение собрано из открытых фактов о компании</span></div><button class="copy-audit-offer" data-copy-audit-offer="${esc(l.id)}" type="button">Скопировать</button></div><div class="audit-offer-grid"><div><span>Сильные стороны</span><p>${esc(data.strengths.join(' · '))}</p></div><div><span>Точки роста и слабые места</span><p>${esc(data.gaps.join(' · '))}</p></div><div><span>Предлагаемая точка продвижения</span><p>${esc(data.recommendation)}</p></div></div><textarea class="offer-text audit-offer-text" id="auditOfferText" aria-label="Оффер по аудиту">${esc(data.message)}</textarea><div class="offer-footer"><span>Проверь факты и добавь свой следующий шаг перед отправкой.</span><span>по открытым данным</span></div></div>`; }
function outreachBlock(l) { const text=l.reviewAnalytics||l.websiteAudit?auditOfferData(l).message:offerVariants(l)[0].text; const candidate=l.whatsapp||(l.websiteAudit?.hasWhatsApp?l.phone:''); const digits=String(candidate||'').replace(/\D/g,''); const waHref=digits?`https://wa.me/${digits}?text=${encodeURIComponent(text)}`:''; const siteHref=l.websiteAudit?.hasWhatsApp&&l.website?l.website:''; const mailHref=l.email?`mailto:${l.email}?subject=${encodeURIComponent('Идея роста для '+l.name)}&body=${encodeURIComponent(text)}`:''; if(!waHref&&!siteHref&&!mailHref)return ''; return `<div class="outreach-panel"><div><div class="detail-label">Быстрый контакт</div><span class="offer-hint">Откроется готовый текст — отправка в WhatsApp или почте подтверждается вами.</span></div><div class="outreach-actions">${waHref?`<a class="outreach-button whatsapp" href="${esc(waHref)}" target="_blank" rel="noreferrer">Открыть WhatsApp с оффером ↗</a>`:siteHref?`<a class="outreach-button whatsapp" href="${esc(siteHref)}" target="_blank" rel="noreferrer">Открыть сайт с WhatsApp ↗</a>`:''}${mailHref?`<a class="outreach-button email" href="${esc(mailHref)}">Создать письмо с оффером ↗</a>`:''}</div></div>`; }
function offerVariants(l) { const meta=serviceMeta[l.service]||serviceMeta.marketing; const ctx=leadContext(l); const company=l.name; const category=ctx.category || 'в своей нише'; const fact=ctx.fact; const reviewHook=ctx.reviewHook; const siteHook=ctx.siteHook; const gentle={tone:'Мягко',text:`Здравствуйте! Нашёл ${company} в ${sourceLabel(l)} — вижу, что вы ${category}. ${fact}. ${reviewHook} ${siteHook} Я помогаю компаниям в Усть-Каменогорске с направлением «${meta.label.toLowerCase()}». ${meta.question} Если удобно, пришлю короткую идею именно под вас.`}; const direct={tone:'По делу',text:`Добрый день! ${company}, есть конкретная идея по направлению «${meta.label.toLowerCase()}»: ${meta.pitch.toLowerCase()} ${reviewHook} ${siteHook} Предлагаю 15 минут созвона или переписки — покажу, с чего начать и сколько это может дать.`}; const partner={tone:'По-человечески',text:`Здравствуйте! Увидел ${company} в ${sourceLabel(l)} и решил написать без длинной презентации. ${fact}. ${reviewHook} ${siteHook} Могу быстро посмотреть ваш текущий процесс и сказать, где есть лёгкая точка роста по направлению «${meta.label.toLowerCase()}». Если тема актуальна, ответьте одним словом — я пришлю первый вариант.`}; return [gentle,direct,partner]; }
function offerBlock(l, tone='Мягко') { const variants=offerVariants(l); const active=variants.find(v=>v.tone===tone)||variants[0]; return `<div class="offer-panel"><div class="offer-panel-head"><div><div class="detail-label">Готовое первое сообщение</div><span class="offer-hint">Выбери тон и адаптируй пару слов под себя</span></div><button class="copy-offer" data-copy-offer="${esc(l.id)}" type="button">Скопировать</button></div><div class="offer-tabs">${variants.map(v=>`<button type="button" class="offer-tab ${v.tone===active.tone?'active':''}" data-offer-tone="${esc(v.tone)}" data-offer-lead="${esc(l.id)}">${esc(v.tone)}</button>`).join('')}</div><textarea class="offer-text" id="offerText" aria-label="Готовое первое сообщение">${esc(active.text)}</textarea><div class="offer-footer"><span>Вопрос в конце оставляет человеку простой повод ответить.</span><span>${metaLabel(l.service)}</span></div></div>`; }
function reviewAuditBlock(l) { const review=l.reviewAnalytics; if(!review && !l.reviewCount)return ''; if(!review)return `<div class="review-audit"><div class="review-head"><div><div class="detail-label">Аудит отзывов</div><span class="review-muted">В карточке указано ${esc(l.reviewCount)} отзывов, детали ещё не загружены.</span></div></div></div>`; const topics=(review.topTopics||[]).map(topic=>`<span class="review-topic">${esc(topic.name)} · ${topic.count}</span>`).join(''); const highlights=(review.highlights||[]).slice(0,2).map(text=>`<li>«${esc(text)}»</li>`).join(''); const risks=(review.risks||[]).slice(0,2).map(text=>`<li class="review-risk">«${esc(text)}»</li>`).join(''); return `<div class="review-audit"><div class="review-head"><div><div class="detail-label">Аудит отзывов</div><strong>${review.sufficient?'Есть материал для оффера':'Нужно больше данных'}</strong></div><span class="review-score">${esc(review.averageRating||'—')} <small>/ 5</small></span></div><p class="review-summary">${esc(review.auditText)}</p><div class="review-metrics"><span class="positive">+${review.positive}</span><span class="neutral">~${review.neutral}</span><span class="negative">−${review.negative}</span><span>${review.sampleSize} прочитано</span></div>${topics?`<div class="review-topics">${topics}</div>`:''}${highlights?`<div class="review-quotes"><div class="review-subhead">Что можно использовать в продаже</div><ul>${highlights}</ul></div>`:''}${risks?`<div class="review-quotes"><div class="review-subhead">Что стоит закрыть предложением</div><ul>${risks}</ul></div>`:''}<div class="review-angle">${esc(review.offerAngle)}</div></div>`; }
 function websiteAuditBlock(l) { const audit=l.websiteAudit; if(!audit)return ''; const issues=(audit.issues||[]).map(x=>`<li>${esc(x)}</li>`).join(''); const strengths=(audit.strengths||[]).map(x=>`<span class="site-strength">${esc(x)}</span>`).join(''); return `<div class="site-audit"><div class="review-head"><div><div class="detail-label">Аудит сайта</div><strong>${audit.ok?'Первый проход готов':'Сайт требует проверки'}</strong></div><span class="site-status">${esc(audit.status||'—')}</span></div><p class="review-summary">${esc(audit.summary||'')}</p>${strengths?`<div class="site-strengths">${strengths}</div>`:''}${issues?`<ul class="site-issues">${issues}</ul>`:''}<div class="review-angle">${esc(audit.offerAngle||'')}</div></div>`; }
 function metaLabel(service) { return serviceMeta[service]?.label || 'Услуга'; }
function visibleLeads(query = '') { const q = query.trim().toLowerCase(); return leads.filter(l => (!currentFocus || l.service === currentFocus) && (!q || [l.name,l.category,l.evidence,l.next,serviceMeta[l.service].label].join(' ').toLowerCase().includes(q))); }
function updateCounts() {
  const hot = leads.filter(l => l.signal === 'hot').length; const ready = leads.filter(l => l.status === 'ready').length; const working = leads.filter(l => ['progress','won'].includes(l.status)).length;
  document.querySelector('#hotCount').textContent = hot; document.querySelector('#todayCount').textContent = ready; document.querySelector('#workCount').textContent = working; document.querySelector('#introLeadCount').textContent = leads.length; document.querySelector('#navLeadCount').textContent = leads.length; document.querySelector('#serviceCount').textContent = leads.filter(l=>l.service==='service').length; document.querySelector('#devCount').textContent = leads.filter(l=>l.service==='dev').length; document.querySelector('#marketingCount').textContent = leads.filter(l=>l.service==='marketing').length; document.querySelector('#aiCount').textContent = leads.filter(l=>l.service==='ai').length; if(document.querySelector('#seoCount')) document.querySelector('#seoCount').textContent = leads.filter(l=>l.service==='seo').length; if(document.querySelector('#contextCount')) document.querySelector('#contextCount').textContent = leads.filter(l=>l.service==='context').length; document.querySelector('#allTabCount').textContent = leads.length; document.querySelector('#readyTabCount').textContent = ready; document.querySelector('#hotTabCount').textContent = hot;
  document.querySelector('#foundFunnel').textContent = leads.length; document.querySelector('#checkedFunnel').textContent = leads.filter(l=>l.signal !== 'cold').length; document.querySelector('#writeFunnel').textContent = ready; document.querySelector('#progressFunnel').textContent = working;
  const total = Math.max(leads.length,1); document.querySelector('#checkedBar').style.width = `${Math.round(leads.filter(l=>l.signal !== 'cold').length/total*100)}%`; document.querySelector('#writeBar').style.width = `${Math.round(ready/total*100)}%`; document.querySelector('#progressBar').style.width = `${Math.round(working/total*100)}%`;
}
function renderSignalList() { const list = [...visibleLeads()].sort((a,b)=>b.score-a.score).slice(0,5); document.querySelector('#signalList').innerHTML = list.map(renderSignal).join('') || `<div class="empty-state"><div class="empty-icon">⌕</div><strong>Сигналов нет</strong><span>Сними фильтр или добавь компанию.</span></div>`; }
function renderSignal(l) { const meta = serviceMeta[l.service]; return `<div class="signal-item" data-id="${l.id}"><div class="signal-icon ${meta.color}">${meta.icon}</div><div class="signal-main"><strong>${esc(l.name)}</strong><span>${esc(l.evidence)}</span></div><div class="signal-score"><span class="score-number ${scoreClass(l.score)}">${l.score}</span><span class="score-label">из 100</span></div><div class="signal-action">Открыть <span>→</span></div></div>`; }
function renderLeadRows(list, alt = false) { return list.map(l => { const meta=serviceMeta[l.service], status=statusMeta[l.status] || statusMeta.muted; return `<tr data-id="${l.id}"><td><div class="company-cell"><div class="company-avatar ${meta.color}">${esc(l.initials || initials(l.name))}</div><div class="company-copy"><strong>${esc(l.name)}</strong><span>${esc(l.category)}</span></div></div></td><td>${alt ? `<span class="service-pill"><i class="${meta.color}"></i>${meta.label}</span>` : `<span class="service-pill"><i class="${meta.color}"></i>${meta.label}</span>`}</td>${alt ? `<td><span class="next-step">${esc(l.evidence)}</span></td>` : `<td><span class="score-pill">${l.score}<span>/ 100</span></span></td><td><span class="next-step">${esc(l.next)}</span></td>`}<td><span class="status-pill ${status.cls}"><i></i>${status.label}</span></td><td><button class="row-action" aria-label="Открыть ${esc(l.name)}">⋯</button></td></tr>`; }).join(''); }
function renderTable() { const q=document.querySelector('#searchInput')?.value || ''; const body=document.querySelector('#leadTableBody'); const list=visibleLeads(q).sort((a,b)=>b.score-a.score); body.innerHTML=renderLeadRows(list); document.querySelector('#emptyState').classList.toggle('hidden', list.length > 0); }
function renderAltTable() { const q=document.querySelector('#searchInputAlt')?.value || ''; let list=visibleLeads(q); if(currentListMode==='ready') list=list.filter(l=>l.status==='ready'); if(currentListMode==='hot') list=list.filter(l=>l.signal==='hot'); list.sort((a,b)=>b.score-a.score); document.querySelector('#leadTableBodyAlt').innerHTML=renderLeadRows(list,true); }
function renderKanban() { const cols=[['ready','Можно писать'],['review','Проверить'],['progress','В работе'],['won','Встреча']]; document.querySelector('#kanban').innerHTML=cols.map(([status,label])=>{const items=leads.filter(l=>l.status===status); return `<section class="kanban-column"><div class="kanban-head"><strong>${label}</strong><span>${items.length}</span></div><div class="kanban-body">${items.map(l=>`<div class="kanban-card" data-id="${l.id}"><strong>${esc(l.name)}</strong><p>${esc(l.next)}</p><div class="kanban-card-footer"><span class="kanban-score">${l.score} / 100</span><span class="kanban-date">${serviceMeta[l.service].label}</span></div></div>`).join('') || '<div class="empty-state"><span>Пока пусто</span></div>'}</div></section>`}).join(''); }
function refresh() { updateCounts(); renderSignalList(); renderTable(); renderAltTable(); renderKanban(); renderPerformance(); const chip=document.querySelector('#activeFilters'); if(chip) chip.innerHTML=currentFocus?`<button class="filter-chip" data-clear-filter="1">${serviceMeta[currentFocus].label} ×</button>`:''; const counter=document.querySelector('#filterCount'); if(counter){counter.classList.toggle('visible',Boolean(currentFocus));counter.textContent=currentFocus?'1':'0';} document.querySelector('#lastSync').textContent='только что'; }
function showToast(text) { const toast=document.querySelector('#toast'); document.querySelector('#toastText').textContent=text; toast.classList.remove('hidden'); clearTimeout(window.__toastTimer); window.__toastTimer=setTimeout(()=>toast.classList.add('hidden'),2600); }
function openDetail(id) { const l=leads.find(x=>x.id===id); if(!l)return; const meta=serviceMeta[l.service]; const status=statusMeta[l.status]||statusMeta.muted; document.querySelector('#detailContent').innerHTML=`<div class="detail-top"><div class="detail-avatar">${esc(l.initials||initials(l.name))}</div><div><h2>${esc(l.name)}</h2><p>${esc(l.category)} · ${meta.label}</p></div><div class="detail-score"><strong>${l.score}</strong><span>оценка сигнала</span></div></div><div class="detail-section"><div class="detail-label">Что известно</div><p class="detail-evidence">${esc(l.evidence)}</p></div>${websiteAuditBlock(l)}${reviewAuditBlock(l)}${agentPlanBlock(l)}${auditOfferBlock(l)}${outreachBlock(l)}${offerBlock(l)}<div class="detail-section"><div class="detail-label">Следующий шаг</div><p class="detail-evidence">${esc(l.next)}</p></div><div class="detail-section detail-actions"><span class="status-pill ${status.cls}"><i></i>${status.label}</span><a class="detail-source" href="${esc(l.source || '#')}" target="_blank" rel="noreferrer">Открыть источник ↗</a><button class="button primary" data-mark-ready="${l.id}" style="margin-left:auto;padding:8px 11px">${l.status==='ready'?'Готово к контакту':'Подготовить контакт'}</button></div><div class="detail-outcomes"><span>Результат контакта:</span><button type="button" data-outcome-status="contacted" data-outcome-lead="${esc(l.id)}">Написал</button><button type="button" data-outcome-status="progress" data-outcome-lead="${esc(l.id)}">Ответил</button><button type="button" data-outcome-status="won" data-outcome-lead="${esc(l.id)}">Встреча / сделка</button></div>`; document.querySelector('#detailModal').classList.remove('hidden'); }
function updateOffer(l, tone) { const panel=document.querySelector('.offer-panel'); if(panel) panel.outerHTML=offerBlock(l,tone); }
function updateOutcome(l, status) { l.status=status; l.lastActionAt=new Date().toISOString(); persist(); refresh(); openDetail(l.id); showToast(`Статус обновлён: ${statusMeta[status].label}`); }
function closeModals() { document.querySelectorAll('.modal-backdrop').forEach(m=>m.classList.add('hidden')); }
function showView(view) { document.querySelectorAll('.content-wrap').forEach(el=>el.classList.add('hidden')); document.querySelector(`#${view}View`).classList.remove('hidden'); document.querySelectorAll('.nav-item[data-view]').forEach(n=>n.classList.toggle('active', n.dataset.view===view)); const titles={overview:'Рабочий стол',leads:'Все лиды',pipeline:'Воронка',sources:'Источники'}; document.querySelector('#viewTitle').textContent=titles[view]; if(view==='leads')renderAltTable(); if(view==='pipeline')renderKanban(); }
function bindEvents() {
  document.querySelectorAll('.nav-item[data-view]').forEach(btn=>btn.addEventListener('click',()=>showView(btn.dataset.view)));
  document.querySelectorAll('.nav-item[data-focus]').forEach(btn=>btn.addEventListener('click',()=>{currentFocus=currentFocus===btn.dataset.focus?null:btn.dataset.focus; showView('overview'); document.querySelector('#activeFilters').textContent=''; refresh(); if(currentFocus) showToast(`Фокус: ${serviceMeta[currentFocus].label}`);}));
  document.querySelector('#searchInput').addEventListener('input',renderTable); document.querySelector('#searchInputAlt').addEventListener('input',renderAltTable);
  document.querySelector('#viewAllHot').addEventListener('click',()=>{showView('leads');currentListMode='hot';document.querySelectorAll('.view-tab').forEach(x=>x.classList.toggle('active',x.dataset.listMode==='hot'));renderAltTable();}); document.querySelector('#pipelineBtn').addEventListener('click',()=>showView('pipeline'));
  document.querySelectorAll('.view-tab').forEach(btn=>btn.addEventListener('click',()=>{currentListMode=btn.dataset.listMode;document.querySelectorAll('.view-tab').forEach(x=>x.classList.toggle('active',x===btn));renderAltTable();}));
  document.querySelector('#refreshBtn').addEventListener('click',()=>{refresh();showToast('Сигналы обновлены');}); document.querySelector('#pipelineReset').addEventListener('click',()=>{leads=leads.map(l=>({...l,status:l.signal==='hot'?'ready':l.status==='won'?'won':'review'}));persist();refresh();showToast('Статусы демо-лидов сброшены');});
  document.querySelectorAll('#addLeadBtn,#addLeadBtnAlt').forEach(btn=>btn.addEventListener('click',()=>document.querySelector('#leadModal').classList.remove('hidden'))); document.querySelectorAll('#closeModal,#cancelModal,#closeDetail').forEach(btn=>btn.addEventListener('click',closeModals));
  document.querySelector('#leadForm').addEventListener('submit',e=>{e.preventDefault();const fd=new FormData(e.target);const name=fd.get('name').trim();const service=fd.get('service');const signal=fd.get('signal');const score=signal==='hot'?84:signal==='warm'?70:54;leads.unshift({id:`lead-${Date.now()}`,name,category:'Добавлено вручную',service,signal,score,evidence:fd.get('evidence').trim(),next:serviceMeta[service].label==='IT-обслуживание'?'Назначить короткий IT-чек':'Подготовить персональное предложение',status:signal==='hot'?'ready':'review',source:fd.get('source').trim(),initials:initials(name)});persist();refresh();closeModals();e.target.reset();showView('overview');showToast('Лид добавлен в очередь');});
  document.addEventListener('click',e=>{const offerTab=e.target.closest('[data-offer-tone]');if(offerTab){const l=leads.find(x=>x.id===offerTab.dataset.offerLead);if(l)updateOffer(l,offerTab.dataset.offerTone);return;} const outcome=e.target.closest('[data-outcome-status]');if(outcome){const l=leads.find(x=>x.id===outcome.dataset.outcomeLead);if(l)updateOutcome(l,outcome.dataset.outcomeStatus);return;} const auditCopy=e.target.closest('[data-copy-audit-offer]');if(auditCopy){const text=document.querySelector('#auditOfferText')?.value||'';const done=()=>showToast('Оффер по аудиту скопирован — проверь факты перед отправкой.');if(navigator.clipboard?.writeText)navigator.clipboard.writeText(text).then(done).catch(()=>showToast('Выдели оффер и скопируй вручную.'));else showToast('Выдели оффер и скопируй вручную.');return;} const copy=e.target.closest('[data-copy-offer]');if(copy){const text=document.querySelector('#offerText')?.value||'';const done=()=>showToast('Сообщение скопировано — можно отправлять после быстрой правки.');if(navigator.clipboard?.writeText)navigator.clipboard.writeText(text).then(done).catch(()=>showToast('Выдели текст и скопируй вручную.'));else showToast('Выдели текст и скопируй вручную.');return;} const row=e.target.closest('[data-id]'); if(row && !e.target.closest('button'))openDetail(row.dataset.id); const mark=e.target.closest('[data-mark-ready]');if(mark){const l=leads.find(x=>x.id===mark.dataset.markReady);if(l){l.status='ready';persist();refresh();openDetail(l.id);showToast('Лид помечен: можно писать');}}});
  document.querySelector('#aboutBtn').addEventListener('click',()=>{showToast('Добавляй факт, источник и следующий шаг — UkaLead соберёт очередь.');}); document.querySelector('#importBtn').addEventListener('click',()=>document.querySelector('#csvInput').click()); document.querySelector('#csvInput').addEventListener('change',handleCsv); document.querySelector('#sourceGrid')?.addEventListener('click',()=>{});
}
function handleCsv(e){const file=e.target.files[0];if(!file)return;const reader=new FileReader();reader.onload=()=>{const lines=String(reader.result).split(/\r?\n/).filter(Boolean);const rows=lines.slice(1).map(line=>line.split(',').map(x=>x.trim().replace(/^"|"$/g,''))).filter(r=>r[0]);rows.forEach(r=>{const service=['service','dev','marketing','ai','seo','context'].includes(r[1])?r[1]:'service';leads.push({id:`lead-${Date.now()}-${Math.random()}`,name:r[0],category:r[2]||'Импортировано',service,signal:'warm',score:68,evidence:r[3]||'Импортированная компания — проверь факт и источник.',next:serviceMeta[service].label==='IT-обслуживание'?'Уточнить текущую IT-поддержку':'Провести первичный аудит',status:'review',source:r[4]||'',initials:initials(r[0])});});persist();refresh();showToast(`Импортировано лидов: ${rows.length}`);e.target.value='';};reader.readAsText(file,'UTF-8');}
const gisState = { items: [], selected: new Set(), service: 'marketing', query: '' };
function gisStatus(text, kind='') { const el=document.querySelector('#gisStatus'); if(!el)return; el.textContent=text; el.className=`gis-status ${kind}`; el.classList.remove('hidden'); }
function gisScore(item, service) { let score=58; if(item.address)score+=8; if(item.category)score+=6; if(item.rating)score+=Math.min(10,Math.round(Number(item.rating)*2)); if(item.reviewCount)score+=Math.min(8,Math.round(Number(item.reviewCount)/20)); if(item.phone||item.whatsapp)score+=6; if(service==='service')score+=5; return Math.min(95,score); }
function normalizeGisItem(item, service, query) { const name=item.name||'Без названия'; const category=item.category||'Организация'; const address=item.address||'Усть-Каменогорск'; const contact=item.phone||item.whatsapp||''; const review=item.reviewAnalytics||null; const websiteAudit=item.websiteAudit||null; const sourceLabel=item.sourceType==='yandex'?'Яндекс Карт':item.sourceType==='google'?'Google Maps':'2ГИС'; const score=Number(item.score)||gisScore(item,service)+(review?.sufficient?5:0)+(websiteAudit?.issues?.length?3:0)+(item.email?3:0); const facts=[`Распарсено из публичной страницы ${sourceLabel}`,address,category,item.rating?`Рейтинг ${item.rating}${item.reviewCount?` · ${item.reviewCount} оценок`:''}`:'',review?.sufficient?`Аудит отзывов: ${review.positive} позитивных, ${review.negative} негативных`:'',item.website?`Сайт: ${item.website}`:'',websiteAudit?.issues?.length?`Аудит сайта: ${websiteAudit.issues[0]}`:'',item.email?`Email: ${item.email}`:'',item.whatsapp?`WhatsApp: ${item.whatsapp}`:'',contact?`Контакт: ${contact}`:''].filter(Boolean); return {id:`${item.sourceType||'map'}-${item.id||name}`,externalId:item.id,name,category,address,phone:item.phone||'',whatsapp:item.whatsapp||'',email:item.email||'',rating:item.rating||'',reviewCount:item.reviewCount||'',reviewAnalytics:review,website:item.website||'',websiteAudit,sourceType:item.sourceType||'2gis',service,signal:score>=80?'hot':score>=68?'warm':'cold',score,evidence:facts.join(' · '),next:service==='service'?'Уточнить текущую IT-поддержку':serviceMeta[service].label==='Разработка'?'Проверить путь заявки и предложить прототип':serviceMeta[service].label==='ИИ и контент'?'Показать пробный пакет контента':review?.sufficient&&review.negative>review.positive?'Предложить аудит клиентского пути по отзывам':websiteAudit?.issues?.length?'Предложить короткий аудит сайта и точки роста':item.email?'Подготовить письмо с точкой роста':'Отправить короткий аудит рекламного пути',status:score>=80?'ready':'review',source:item.source||'https://2gis.kz/ustkam',initials:initials(name)}; }
function renderGisResults() { const list=document.querySelector('#gisResultList'); if(!list)return; document.querySelector('#gisResultCount').textContent=`${gisState.items.length} найдено · ${gisState.selected.size} выбрано`; list.innerHTML=gisState.items.map(item=>{const label=item.sourceType==='yandex'?'Яндекс Карты':item.sourceType==='google'?'Google Maps':'2ГИС';return `<label class="gis-result"><input type="checkbox" data-gis-id="${esc(item.id)}" ${gisState.selected.has(item.id)?'checked':''}/><span class="gis-result-main"><strong>${esc(item.name)}</strong><span>${esc(item.address||'Усть-Каменогорск')} · ${esc(item.category)}</span><small>${esc(item.evidence)}</small><a class="gis-open" href="${esc(item.source)}" target="_blank" rel="noreferrer" onclick="event.stopPropagation()">Открыть карточку ${label} ↗</a></span><span class="gis-result-score">${item.score}<span>из 100</span></span></label>`}).join(''); list.querySelectorAll('[data-gis-id]').forEach(box=>box.addEventListener('change',()=>{box.checked?gisState.selected.add(box.dataset.gisId):gisState.selected.delete(box.dataset.gisId);document.querySelector('#gisResultCount').textContent=`${gisState.items.length} найдено · ${gisState.selected.size} выбрано`; })); document.querySelector('#gisResults').classList.remove('hidden'); }
function configureMapSource(source='2gis') { const configs={'2gis':{title:'Распарсить компании из 2ГИС',url:'https://2gis.kz/ustkam/search/Мебель%20на%20заказ',help:'Публичная HTML-страница 2ГИС: карточки, отзывы, сайт и опубликованные контакты.'},yandex:{title:'Распарсить компании из Яндекс Карт',url:'https://yandex.ru/maps/?text=мебель%20Усть-Каменогорск',help:'Публичная HTML-страница Яндекс Карт: карточки и дополнительные email, если они видны в источнике.'},google:{title:'Распарсить компании из Google Maps',url:'https://www.google.com/maps/search/?api=1&query=мебель%20Усть-Каменогорск',help:'Публичная выдача Google Maps. Доступность результатов зависит от того, что источник отдаёт без входа и CAPTCHA.'}}; const cfg=configs[source]||configs['2gis']; const title=document.querySelector('#gisModalTitle'); const input=document.querySelector('#gisForm input[name="url"]'); const help=document.querySelector('.gis-help'); if(title)title.textContent=cfg.title;if(input)input.value=cfg.url;if(help)help.textContent=cfg.help; }
function openGisModal(source='2gis') { const modal=document.querySelector('#gisModal'); if(!modal)return; configureMapSource(source); document.querySelector('#gisStatus')?.classList.add('hidden'); document.querySelector('#gisResults')?.classList.add('hidden'); modal.classList.remove('hidden'); }
async function searchGis(e) { e.preventDefault(); const form=e.currentTarget; const data=new FormData(form); const url=String(data.get('url')||'').trim(); const service=String(data.get('service')||'marketing'); const limit=Math.min(50,Math.max(1,Number(data.get('limit')||20))); if(!url){gisStatus('Вставь публичную ссылку на поиск карт.','error');return;} gisState.service=service;gisState.query=url;gisState.items=[];gisState.selected=new Set(); const btn=document.querySelector('#gisSearchBtn'); if(btn){btn.disabled=true;btn.innerHTML='Читаю страницу <span>…</span>';} gisStatus('Читаю публичную HTML-страницу источника…'); try { const response=await fetch('/api/parse-2gis',{method:'POST',headers:{'content-type':'application/json'},body:JSON.stringify({url,service,limit})}); const payload=await response.json().catch(()=>({})); if(!response.ok||payload.error) throw new Error(payload.error||`HTTP ${response.status}`); const raw=payload.leads||[]; gisState.items=raw.map(item=>normalizeGisItem(item,service,url)); gisState.selected=new Set(gisState.items.map(item=>item.id)); if(!gisState.items.length){gisStatus('На странице не нашли карточки компаний. Проверь ссылку и доступность публичной выдачи.','error');return;} gisStatus(`Готово: распознано ${gisState.items.length} компаний. Проверь факты и добавь выбранные карточки в очередь.`, 'success'); renderGisResults(); } catch(error) { gisStatus(`Парсер источника не вернул результаты: ${String(error?.message||error)}`,'error'); document.querySelector('#gisResults')?.classList.add('hidden'); } finally { if(btn){btn.disabled=false;btn.innerHTML='Распарсить страницу <span>↗</span>'; } } }
function importGisLeads() { const picked=gisState.items.filter(item=>gisState.selected.has(item.id)); if(!picked.length){gisStatus('Выбери хотя бы одну компанию.','error');return;} let added=0,updated=0; picked.forEach(item=>{const created=addBatchLead({...item});created?added++:updated+=1;}); persist();refresh();closeModals();showView('overview');showToast(`Карты: добавлено ${added}, обновлено ${updated} карточек`); }
function initGisImporter() { const trigger=document.querySelector('[data-open-source="2gis"]'); if(trigger){trigger.setAttribute('aria-label','Запустить живой импорт 2ГИС');trigger.addEventListener('click',()=>openGisModal('2gis')); const card=trigger.closest('.source-card'); if(card&&!card.querySelector('#liveImportBtn')){const button=document.createElement('button');button.id='liveImportBtn';button.className='source-inline-button';button.textContent='Живой импорт компаний →';button.addEventListener('click',()=>openGisModal('2gis'));card.querySelector('div:nth-child(2)')?.appendChild(button);}} document.querySelectorAll('[data-open-map-source]').forEach(button=>button.addEventListener('click',()=>openGisModal(button.dataset.openMapSource))); document.querySelector('#gisForm')?.addEventListener('submit',searchGis); document.querySelector('#importGisBtn')?.addEventListener('click',importGisLeads); document.querySelector('#closeGisModal')?.addEventListener('click',closeModals); document.querySelector('#cancelGis')?.addEventListener('click',closeModals); }
const nichePresets=[{id:'furniture',label:'Мебель и кухни',query:'мебель на заказ',service:'marketing'},{id:'beauty',label:'Салоны красоты',query:'салон красоты',service:'service'},{id:'education',label:'Учебные центры',query:'учебный центр',service:'ai'},{id:'auto',label:'Автосервисы',query:'автосервис',service:'service'},{id:'clinics',label:'Медицинские центры',query:'медицинский центр',service:'marketing'},{id:'shops',label:'Магазины и услуги',query:'магазин',service:'dev'}];
let batchResults=[];
function injectModal(markup){document.body.insertAdjacentHTML('beforeend',markup);}
function addBatchLead(item){const key=item.name.toLowerCase().trim();const existing=leads.find(l=>l.name.toLowerCase().trim()===key);if(existing){Object.assign(existing,{reviewAnalytics:item.reviewAnalytics||existing.reviewAnalytics,website:item.website||existing.website,websiteAudit:item.websiteAudit||existing.websiteAudit,email:item.email||existing.email,whatsapp:item.whatsapp||existing.whatsapp,phone:item.phone||existing.phone,sourceType:item.sourceType||existing.sourceType,rating:item.rating||existing.rating,reviewCount:item.reviewCount||existing.reviewCount,evidence:item.evidence||existing.evidence,score:Math.max(existing.score||0,item.score||0)});return false;}leads.unshift(item);return true;}
function openBatchModal(){document.querySelector('#batchModal')?.classList.remove('hidden');document.querySelector('#batchStatus')?.classList.add('hidden');}
async function runBatchSearch(e){e.preventDefault();const chosen=[...document.querySelectorAll('#batchForm input[name="niche"]:checked')].map(x=>nichePresets.find(p=>p.id===x.value)).filter(Boolean);if(!chosen.length){const s=document.querySelector('#batchStatus');s.textContent='Выбери хотя бы одну нишу.';s.className='batch-status error';s.classList.remove('hidden');return;}const btn=document.querySelector('#batchSearchBtn');btn.disabled=true;btn.textContent='Собираю компании…';const status=document.querySelector('#batchStatus');status.textContent=`Запускаю ${chosen.length} поисковых запросов 2ГИС…`;status.className='batch-status';status.classList.remove('hidden');try{const responses=await Promise.all(chosen.map(async preset=>{const response=await fetch('/api/parse-2gis',{method:'POST',headers:{'content-type':'application/json'},body:JSON.stringify({url:`https://2gis.kz/ustkam/search/${encodeURIComponent(preset.query)}`,service:preset.service,limit:10})});const payload=await response.json();return (payload.leads||[]).map(item=>normalizeGisItem(item,preset.service,preset.query));}));batchResults=[].concat(...responses).filter((item,index,arr)=>arr.findIndex(x=>x.name.toLowerCase()===item.name.toLowerCase())===index);const fresh=batchResults.filter(item=>!leads.some(l=>l.name.toLowerCase()===item.name.toLowerCase())).length;status.textContent=`Готово: ${batchResults.length} компаний, из них ${fresh} новых. Нажми «Добавить новые лиды».`;status.className='batch-status success';document.querySelector('#batchImportBtn').classList.remove('hidden');}catch(error){status.textContent=`Пакетный поиск не завершён: ${String(error?.message||error)}`;status.className='batch-status error';}finally{btn.disabled=false;btn.textContent='Собрать компании';}}
function importBatchLeads(){let added=0,updated=0;batchResults.forEach(item=>{if(addBatchLead(item))added+=1;else updated+=1;});persist();refresh();closeModals();showView('overview');showToast(`Пакет: добавлено ${added}, обновлено ${updated} карточек`);batchResults=[];}
function openDailyQueue(){const items=leads.filter(l=>['ready','review'].includes(l.status)).sort((a,b)=>b.score-a.score).slice(0,8);const list=items.length?items.map(l=>`<button class="queue-item" data-queue-lead="${esc(l.id)}"><span class="queue-score">${l.score}</span><span><strong>${esc(l.name)}</strong><small>${esc(l.next||'Подготовить персональное предложение')}</small></span><span class="queue-arrow">→</span></button>`).join(''):'<div class="empty-state"><strong>Очередь пуста</strong><span>Новые лиды появятся после импорта.</span></div>';document.querySelector('#queueList').innerHTML=list;document.querySelector('#queueCount').textContent=`${items.length} приоритетных действий`;document.querySelector('#queueModal').classList.remove('hidden');}
function openServicePackages(){document.querySelector('#packagesModal').classList.remove('hidden');}
function renderPerformance(){const panel=document.querySelector('#performancePanel');if(!panel)return;const contacted=leads.filter(l=>['contacted','progress','won'].includes(l.status)).length;const replied=leads.filter(l=>['progress','won'].includes(l.status)).length;const won=leads.filter(l=>l.status==='won').length;const audited=leads.filter(l=>l.reviewAnalytics?.sufficient).length;const rate=contacted?Math.round(replied/contacted*100):0;document.querySelector('#performanceMetrics').innerHTML=`<div><strong>${contacted}</strong><span>контактов</span></div><div><strong>${replied}</strong><span>ответов</span></div><div><strong>${rate}%</strong><span>ответов</span></div><div><strong>${won}</strong><span>встреч / сделок</span></div><div><strong>${audited}</strong><span>аудитов отзывов</span></div>`;}
function injectEnhancements(){const introActions=document.querySelector('#overviewView .intro-actions');if(introActions&&!document.querySelector('#queueBtn')){const queue=document.createElement('button');queue.id='queueBtn';queue.className='button secondary';queue.innerHTML='<span>☀</span> Очередь дня';queue.addEventListener('click',openDailyQueue);introActions.prepend(queue);}if(introActions&&!document.querySelector('#packagesBtn')){const packages=document.createElement('button');packages.id='packagesBtn';packages.className='button secondary';packages.innerHTML='<span>⌁</span> IT-пакеты';packages.addEventListener('click',openServicePackages);introActions.prepend(packages);}const sourceCard=document.querySelector('[data-open-source="2gis"]')?.closest('.source-card');if(sourceCard&&!document.querySelector('#batchOpenBtn')){const button=document.createElement('button');button.id='batchOpenBtn';button.className='source-inline-button';button.textContent='Пакетный поиск по нишам →';button.addEventListener('click',openBatchModal);sourceCard.querySelector('div:nth-child(2)')?.appendChild(button);}const stats=document.querySelector('#overviewView .stats-grid');if(stats&&!document.querySelector('#performancePanel')){stats.insertAdjacentHTML('afterend','<section class="panel performance-panel" id="performancePanel"><div class="panel-header"><div><div class="section-kicker">КОНВЕРСИЯ И КАЧЕСТВО</div><h2>Результат работы</h2></div><span class="performance-note">обновляется по статусам лидов</span></div><div class="performance-metrics" id="performanceMetrics"></div></section>');}if(!document.querySelector('#batchModal'))injectModal(`<div class="modal-backdrop hidden" id="batchModal"><div class="modal batch-modal" role="dialog" aria-modal="true"><button class="modal-close" data-close-enhancement>×</button><div class="section-kicker">ПАКЕТНЫЙ ПОИСК</div><h2>Собрать лиды по нишам</h2><p class="modal-subtitle">UkaLead последовательно прочитает публичные страницы 2ГИС и уберёт дубли.</p><form id="batchForm"><div class="batch-grid">${nichePresets.map(p=>`<label class="batch-option"><input type="checkbox" name="niche" value="${p.id}" ${['furniture','beauty','education'].includes(p.id)?'checked':''}/><span><strong>${p.label}</strong><small>${p.query} · ${metaLabel(p.service)}</small></span></label>`).join('')}</div><div class="form-actions"><button type="button" class="button secondary" data-close-enhancement>Отмена</button><button class="button primary" id="batchSearchBtn" type="submit">Собрать компании <span>→</span></button></div></form><div class="batch-status hidden" id="batchStatus"></div><button class="button primary hidden" id="batchImportBtn" type="button">Добавить новые лиды</button></div></div>`);if(!document.querySelector('#queueModal'))injectModal(`<div class="modal-backdrop hidden" id="queueModal"><div class="modal queue-modal" role="dialog" aria-modal="true"><button class="modal-close" data-close-enhancement>×</button><div class="section-kicker">РАБОТА НА СЕГОДНЯ</div><h2>Приоритетная очередь</h2><p class="modal-subtitle" id="queueCount">0 приоритетных действий</p><div class="queue-list" id="queueList"></div></div></div>`);if(!document.querySelector('#packagesModal'))injectModal(`<div class="modal-backdrop hidden" id="packagesModal"><div class="modal packages-modal" role="dialog" aria-modal="true"><button class="modal-close" data-close-enhancement>×</button><div class="section-kicker">АБОНЕНТСКОЕ IT</div><h2>Пакеты сопровождения</h2><p class="modal-subtitle">Готовый разговор начинается с понятного результата и фиксированного объёма.</p><div class="package-list"><article><strong>Базовый</strong><span>рабочие места · резервные копии · помощь сотрудникам</span><b>от 35 000 ₸ / мес</b></article><article><strong>Бизнес</strong><span>сеть · безопасность · сайт · контроль доступов</span><b>от 75 000 ₸ / мес</b></article><article><strong>Под ключ</strong><span>постоянное сопровождение · аварийная поддержка · развитие</span><b>от 140 000 ₸ / мес</b></article></div><button class="button primary" data-close-enhancement>Вернуться к лидам</button></div></div>`);document.querySelector('#batchForm')?.addEventListener('submit',runBatchSearch);document.querySelector('#batchImportBtn')?.addEventListener('click',importBatchLeads);document.querySelectorAll('[data-close-enhancement]').forEach(button=>button.addEventListener('click',closeModals));document.querySelector('#queueList')?.addEventListener('click',e=>{const button=e.target.closest('[data-queue-lead]');if(button){closeModals();openDetail(button.dataset.queueLead);}});renderPerformance();}
function registerWebMcp() {
  const context = typeof document !== 'undefined' ? document.modelContext : undefined;
  if (!context?.registerTool) return;
  const lifecycle = new AbortController();
  const safeLead = l => ({ id:l.id, name:l.name, category:l.category, service:serviceMeta[l.service].label, score:l.score, signal:l.signal, status:l.status, evidence:l.evidence, next:l.next, source:l.source || null });
  Promise.resolve(context.registerTool({ name:'search_leads', title:'Search UkaLead leads', description:'Find leads in the current UkaLead workspace by service, status, or text. Read-only.', inputSchema:{type:'object',properties:{query:{type:'string'},service:{type:'string',enum:['service','dev','marketing','ai','seo','context']},status:{type:'string'}},additionalProperties:false}, annotations:{readOnlyHint:true,untrustedContentHint:false}, execute(input={}){ const query=String(input.query||'').toLowerCase(); const result=leads.filter(l=>(!input.service||l.service===input.service)&&(!input.status||l.status===input.status)&&(!query||[l.name,l.category,l.evidence,l.next].join(' ').toLowerCase().includes(query))).slice(0,20).map(safeLead); return {count:result.length,leads:result}; } },{signal:lifecycle.signal})).catch(()=>{});
  Promise.resolve(context.registerTool({ name:'create_lead', title:'Create a lead', description:'Add one company to the visible UkaLead queue with a service, evidence, and optional source URL.', inputSchema:{type:'object',properties:{name:{type:'string'},service:{type:'string',enum:['service','dev','marketing','ai','seo','context']},evidence:{type:'string'},source:{type:'string'}},required:['name','service','evidence'],additionalProperties:false}, annotations:{readOnlyHint:false,untrustedContentHint:false}, execute(input={}){ const name=String(input.name||'').trim(), evidence=String(input.evidence||'').trim(), service=input.service; if(!name||!evidence||!serviceMeta[service]) throw new Error('name, service, and evidence are required'); const lead={id:`lead-${Date.now()}`,name,category:'Добавлено через AI-инструмент',service,signal:'warm',score:68,evidence,next:service==='service'?'Уточнить текущую IT-поддержку':'Провести первичный аудит',status:'review',source:String(input.source||''),initials:initials(name)}; leads.unshift(lead); persist(); refresh(); showToast('Лид добавлен в очередь'); return safeLead(lead); } },{signal:lifecycle.signal})).catch(()=>{});
  window.__ukaleadWebMcpLifecycle = lifecycle;
}
document.addEventListener('DOMContentLoaded',()=>{bindEvents();injectEnhancements();refresh();registerWebMcp();initGisImporter(); const filterOrder=[null,'service','dev','marketing','ai','seo','context']; document.querySelector('#filterBtn').addEventListener('click',()=>{currentFocus=filterOrder[(filterOrder.indexOf(currentFocus)+1)%filterOrder.length]; const chip=document.querySelector('#activeFilters'); chip.innerHTML=currentFocus?`<button class="filter-chip" data-clear-filter="1">${serviceMeta[currentFocus].label} ×</button>`:''; document.querySelector('#filterCount').classList.toggle('visible',Boolean(currentFocus)); document.querySelector('#filterCount').textContent=currentFocus?'1':'0'; refresh(); showToast(currentFocus?`Фильтр: ${serviceMeta[currentFocus].label}`:'Фильтр снят'); }); document.querySelector('#activeFilters').addEventListener('click',()=>{currentFocus=null;document.querySelector('#filterCount').classList.remove('visible');refresh();});});

// Детерминированный автопилот: каждый агент выполняет прозрачное правило без ИИ и внешнего API.
const agentDefinitions = [
  { id:'collector', icon:'⌕', title:'Сборщик источников', text:'фиксирует источник и доступные публичные контакты' },
  { id:'normalizer', icon:'≋', title:'Нормализатор', text:'приводит карточки к единому формату' },
  { id:'deduper', icon:'◇', title:'Дедупликатор', text:'убирает повторные компании по названию' },
  { id:'website', icon:'⌂', title:'Агент сайта', text:'отделяет владельцев сайта от компаний без сайта' },
  { id:'review', icon:'✦', title:'Агент отзывов', text:'читает доступную аналитику рейтинга и отзывов' },
  { id:'seo', icon:'⌖', title:'SEO-агент', text:'добавляет SEO для сайтов и локальные точки роста' },
  { id:'ads', icon:'◌', title:'Агент рекламы', text:'готовит связку Google Ads + Яндекс Директ' },
  { id:'offer', icon:'↗', title:'Агент оффера', text:'собирает живое сообщение под найденный факт' },
  { id:'queue', icon:'☷', title:'Агент очереди', text:'ставит лиды в порядок по контакту и сигналу' }
];
let agentRun = loadAgentRun();
function loadAgentRun(){ try { return JSON.parse(localStorage.getItem('ukalead-agent-run')) || {status:'idle',steps:agentDefinitions.map(x=>({id:x.id,status:'pending'})),updatedAt:null}; } catch { return {status:'idle',steps:agentDefinitions.map(x=>({id:x.id,status:'pending'})),updatedAt:null}; } }
function saveAgentRun(){ localStorage.setItem('ukalead-agent-run',JSON.stringify(agentRun)); }
function agentStepStatus(id){ return agentRun.steps?.find(x=>x.id===id)?.status || 'pending'; }
function hasWebsite(l){ return Boolean(String(l.website||'').trim() || l.websiteAudit?.url); }
function recommendedTracks(l){
  const tracks=[]; const category=String(l.category||'').toLowerCase();
  if(l.service && serviceMeta[l.service]) tracks.push(l.service);
  if(hasWebsite(l)){ tracks.push('seo','context'); } else { tracks.push('dev','marketing'); }
  if(l.reviewAnalytics?.sufficient || Number(l.reviewCount||0)>=10) tracks.push('ai');
  if(l.phone || l.whatsapp || l.email || category.includes('филиал') || Number(l.reviewCount||0)>=25) tracks.push('service');
  return [...new Set(tracks)].filter(x=>serviceMeta[x]);
}
function trackReason(track,l){
  if(track==='seo') return hasWebsite(l) ? 'есть сайт, который можно превратить в стабильный локальный источник заявок' : 'сайт стоит создать перед продвижением';
  if(track==='context') return hasWebsite(l) ? 'горячие запросы можно вести на готовую страницу через Google Ads и Яндекс Директ' : 'сначала нужна посадочная страница, затем тест рекламы';
  if(track==='service') return 'публичный контакт и поток обращений дают повод предложить абонентское IT-сопровождение';
  if(track==='ai') return 'отзывы и факты компании можно быстро превратить в регулярный контент';
  if(track==='dev') return 'нет сайта или понятного пути заявки — нужен небольшой цифровой прототип';
  if(track==='marketing') return 'нужно связать источник трафика, оффер и первый контакт';
  return serviceMeta[track]?.label || 'точка роста';
}
function agentActions(l,tracks){
  return tracks.slice(0,4).map(track=>{
    if(track==='seo') return {track,label:'SEO для сайта',action:hasWebsite(l)&&l.websiteAudit?.issues?.length?`закрыть первым пунктом аудита: ${l.websiteAudit.issues[0]}`:'проверить локальные запросы, title, контакты и страницы услуг'};
    if(track==='context') return {track,label:'Контекст Google / Яндекс',action:'собрать тестовую кампанию Google Ads и Яндекс Директ с отдельными целями звонка и заявки'};
    if(track==='service') return {track,label:'IT-обслуживание',action:'проверить резервные копии, доступы, безопасность и канал быстрых заявок сотрудников'};
    if(track==='ai') return {track,label:'ИИ и контент',action:'собрать 14-дневный пакет постов, кейсов и ответов на частые вопросы'};
    if(track==='dev') return {track,label:'Разработка',action:'сделать короткую форму расчёта или страницу заявки и проверить конверсию'};
    return {track,label:serviceMeta[track].label,action:'провести короткий аудит пути клиента и предложить один измеримый тест'};
  });
}
function agentOfferText(l){
  const tracks=l.serviceRecommendations||recommendedTracks(l); const top=tracks[0]||'marketing'; const meta=serviceMeta[top]||serviceMeta.marketing; const source=sourceLabel(l); const site=hasWebsite(l)?' У сайта уже есть база для роста.':''; const fact=l.websiteAudit?.issues?.[0] || (l.reviewAnalytics?.offerAngle) || 'в карточке уже есть публичный сигнал для первого контакта';
  const platform=top==='context'?' Google Ads и Яндекс Директ':top==='seo'?' локальное SEO':` направления «${meta.label.toLowerCase()}»`;
  return `Здравствуйте! ${l.name}, нашёл вас в ${source} и быстро посмотрел открытые данные.${site} Вижу точку роста: ${fact}. Предлагаю начать с ${platform}: ${meta.pitch.toLowerCase()} Могу прислать три конкретных шага и первый вариант под вашу компанию. Если актуально, ответьте — покажу без длинной презентации.`;
}
function agentPlanBlock(l){
  if(!l.agentPlan?.length && !l.serviceRecommendations?.length) return '';
  const actions=(l.agentPlan||[]).slice(0,4).map(x=>`<li><span class="agent-plan-dot ${serviceClass(x.track)}"></span><div><strong>${esc(x.label)}</strong><span>${esc(x.action)}</span></div></li>`).join('');
  const chips=(l.serviceRecommendations||[]).slice(0,5).map(track=>`<span class="agent-track-chip ${serviceClass(track)}">${esc(serviceMeta[track].label)}</span>`).join('');
  const offer=l.agentOffer||agentOfferText(l);
  return `<div class="agent-plan-panel"><div class="offer-panel-head"><div><div class="detail-label">Маршрут агентов</div><span class="offer-hint">Правила собраны из фактов карточки, сайта и отзывов</span></div><button class="copy-agent-offer" data-copy-agent-offer="${esc(l.id)}" type="button">Скопировать оффер</button></div><div class="agent-track-list">${chips}</div><ul class="agent-plan-list">${actions}</ul><textarea class="offer-text agent-offer-text" id="agentOfferText" aria-label="Оффер автопилота">${esc(offer)}</textarea><div class="offer-footer"><span>Проверь факты и отправь через WhatsApp или почту вручную.</span><span>без ИИ-ключа</span></div></div>`;
}
function renderAgentPanel(){
  const panel=document.querySelector('#agentPanel'); if(!panel)return;
  const done=agentRun.steps?.filter(x=>x.status==='done').length||0; const total=agentDefinitions.length; const enriched=leads.filter(l=>l.serviceRecommendations?.length).length;
  panel.querySelector('.agent-progress').textContent=agentRun.status==='running'?`Выполняется этап ${done+1} из ${total}`:agentRun.status==='done'?`Готово · ${enriched} лидов получили маршрут`:'Готов к запуску по текущей очереди';
  panel.querySelector('.agent-progress-bar').style.width=`${Math.round(done/total*100)}%`;
  panel.querySelector('.agent-list').innerHTML=agentDefinitions.map(a=>`<div class="agent-item ${agentStepStatus(a.id)}"><span class="agent-icon">${a.icon}</span><div><strong>${a.title}</strong><small>${a.text}</small></div><b>${agentStepStatus(a.id)==='done'?'Готово':agentStepStatus(a.id)==='running'?'…':'Ожидает'}</b></div>`).join('');
  const btn=panel.querySelector('#agentPilotBtn'); if(btn){btn.disabled=agentRun.status==='running';btn.textContent=agentRun.status==='running'?'Автопилот работает…':agentRun.status==='done'?'Запустить повторно':'Запустить автопилот';}
}
function processAgentStage(id){
  if(id==='collector') leads.forEach(l=>{l.agentSource=sourceLabel(l);});
  if(id==='normalizer') leads.forEach(l=>{l.category=l.category||'Организация';l.initials=l.initials||initials(l.name);l.evidence=String(l.evidence||'').trim();});
  if(id==='deduper'){ const seen=new Set(); leads=leads.filter(l=>{const key=String(l.name||'').toLowerCase().trim();if(seen.has(key))return false;seen.add(key);return true;}); }
  if(id==='website') leads.forEach(l=>{l.agentWebsiteSignal=hasWebsite(l)?'Сайт найден — можно запускать SEO и контекст':'Сайт не найден — сначала предложить страницу или прототип';});
  if(id==='review') leads.forEach(l=>{l.agentReviewSignal=l.reviewAnalytics?.sufficient?'Отзывы достаточны для персонального оффера':'Отзывы использовать осторожно, данных мало';});
  if(id==='seo' || id==='ads') leads.forEach(l=>{l.serviceRecommendations=recommendedTracks(l);l.agentPlan=agentActions(l,l.serviceRecommendations);});
  if(id==='offer') leads.forEach(l=>{l.serviceRecommendations=l.serviceRecommendations||recommendedTracks(l);l.agentPlan=l.agentPlan||agentActions(l,l.serviceRecommendations);l.agentOffer=agentOfferText(l);});
  if(id==='queue') leads.sort((a,b)=>(b.score||0)-(a.score||0)).forEach((l,index)=>{l.agentQueue=index+1;l.next=l.agentPlan?.[0]?.action||l.next||'Подготовить персональное предложение';if(['review','muted'].includes(l.status)&&l.score>=75)l.status='ready';});
  persist();
}
function runAgentPilot(){
  if(agentRun.status==='running')return;
  agentRun={status:'running',steps:agentDefinitions.map(x=>({id:x.id,status:'pending'})),updatedAt:new Date().toISOString()}; saveAgentRun(); renderAgentPanel();
  let index=0; const tick=()=>{if(index>=agentDefinitions.length){agentRun.status='done';agentRun.updatedAt=new Date().toISOString();saveAgentRun();refresh();renderAgentPanel();showToast(`Автопилот завершён: обработано ${leads.length} лидов`);return;} const id=agentDefinitions[index].id; agentRun.steps[index].status='running';saveAgentRun();renderAgentPanel();setTimeout(()=>{processAgentStage(id);agentRun.steps[index].status='done';saveAgentRun();renderAgentPanel();index+=1;setTimeout(tick,130);},220);}; tick();
}
function initAgentPilot(){
  const intro=document.querySelector('#overviewView .intro-actions'); if(intro&&!document.querySelector('#agentPilotBtn')){const button=document.createElement('button');button.id='agentPilotBtn';button.className='button secondary';button.innerHTML='☷ Автопилот агентов';button.addEventListener('click',runAgentPilot);intro.prepend(button);}
  const anchor=document.querySelector('#performancePanel')||document.querySelector('#overviewView .stats-grid'); if(anchor&&!document.querySelector('#agentPanel')){anchor.insertAdjacentHTML('afterend',`<section class="panel agent-panel" id="agentPanel"><div class="panel-header"><div><div class="section-kicker">ДЕТЕРМИНИРОВАННАЯ АВТОМАТИЗАЦИЯ</div><h2>Автопилот агентов</h2></div><span class="agent-progress">Готов к запуску по текущей очереди</span></div><div class="agent-progress-track"><div class="agent-progress-bar"></div></div><div class="agent-list"></div><p class="agent-footnote">Агенты работают по прозрачным правилам: собирают публичные факты, рекомендуют SEO, контекст Google/Яндекс, IT-сопровождение и следующий шаг. Отправка сообщений остаётся ручной.</p></section>`);}
  renderAgentPanel();
}
document.addEventListener('click',e=>{const copy=e.target.closest('[data-copy-agent-offer]');if(copy){const text=document.querySelector('#agentOfferText')?.value||'';if(navigator.clipboard?.writeText)navigator.clipboard.writeText(text).then(()=>showToast('Оффер автопилота скопирован')).catch(()=>showToast('Выдели оффер и скопируй вручную.'));else showToast('Выдели оффер и скопируй вручную.');}});
document.addEventListener('DOMContentLoaded',()=>{initAgentPilot();});


